async function loadLearning(){try{const [d,p]=await Promise.all([api('/api/learning'),api('/api/projects/portfolio')]);$('learnMissions').textContent=d.metrics?.missions??0;$('learnQuality').textContent=(d.metrics?.averageQuality??0)+'/100';$('learnRepairs').textContent=d.metrics?.repairRuns??0;$('learnProjects').textContent=d.metrics?.projects??0;$('learningInsights').innerHTML=(d.insights||[]).slice(0,20).map(x=>`<div class="card"><div class="row"><b>${escapeHtml(x.title)}</b><span class="chip">${x.qualityScore}/100</span></div><p>${escapeHtml(x.lesson||'')}</p><small>${escapeHtml(x.evidence||'')}</small></div>`).join('')||'<div class="empty">Complete a mission to begin automatic learning.</div>';$('learningProjects').innerHTML=(p.projects||[]).map(x=>`<div class="card"><div class="row"><b>${escapeHtml(x.name)}</b>${x.active?'<span class="chip">active</span>':''}</div><p>${x.completed} completed · ${x.activeMissions} active · quality ${x.averageQuality}/100</p><small>${x.missions} total missions · ${x.memories} memories · ${x.decisions} decisions · ${x.lessons} lessons</small></div>`).join('')||'<div class="empty">No project folders detected.</div>'}catch(e){$('learningInsights').innerHTML=`<div class="card"><b>Learning Lab error</b><small>${escapeHtml(e.message)}</small></div>`}}window.loadLearning=loadLearning;

async function loadChief(){try{const [d,p]=await Promise.all([api('/api/chief-of-staff'),api('/api/projects/context')]);$('chiefProposed').textContent=d.counts?.proposed??0;$('chiefApproved').textContent=d.counts?.approved??0;$('chiefDismissed').textContent=d.counts?.dismissed??0;$('chiefProjects').textContent=p.projects?.length??0;$('chiefProposalList').innerHTML=(d.proposals||[]).map(x=>`<div class="card"><div class="row"><b>${escapeHtml(x.title)}</b><span class="chip">${escapeHtml(x.kind)}</span></div><p>${escapeHtml(x.reason||'')}</p><small>${escapeHtml(x.status||'proposed')}${x.conflicts?.length?` · ${x.conflicts.length} prior-decision matches`:''}</small>${x.status==='proposed'?`<div class="row"><button onclick="decideChief('${x.id}','approve')">Approve → mission</button><button class="secondary" onclick="decideChief('${x.id}','dismiss')">Dismiss</button></div>`:''}</div>`).join('')||'<div class="empty">No proposals. Generate proposals from your inbox, goals, and failed missions.</div>';$('chiefProjectList').innerHTML=(p.projects||[]).map(x=>`<div class="card"><div class="row"><b>${escapeHtml(x.name)}</b>${x.active?'<span class="chip">active</span>':''}</div><small>${x.missions} missions · ${x.memories} linked memories · ${x.decisions} decisions · ${x.lessons} lessons</small></div>`).join('')||'<div class="empty">No project folders detected yet.</div>'}catch(e){$('chiefProposalList').innerHTML=`<div class="card"><b>Chief of Staff error</b><small>${escapeHtml(e.message)}</small></div>`}}
