    $('cmdTriage').innerHTML=(d.triage.items||[]).slice(0,12).map(x=>`<div class="card"><div class="row"><b>${escapeHtml(x.title)}</b><span class="chip">${escapeHtml(x.kind)} · ${Math.round(x.priority)}</span></div><small>${escapeHtml(x.detail||'')}</small></div>`).join('')||'<div class="card emptyState">Queue clear.</div>';
    $('cmdHealth').innerHTML=(d.health.checks||[]).map(x=>`<div class="card"><div class="row"><b>${x.ok?'✓':'○'} ${escapeHtml(x.label)}</b><span class="chip">${x.ok?'OK':'Attention'}</span></div><small>${escapeHtml(x.detail||'')}</small></div>`).join('');
    $('cmdOfflineChecks').innerHTML=(d.offline.checks||[]).map(x=>`<div class="card"><div class="row"><b>${x.ok?'✓':'○'} ${escapeHtml(x.label)}</b><span class="chip">${x.ok?'Ready':'Gap'}</span></div><small>${escapeHtml(x.detail||'')}</small></div>`).join('');
    $('cmdKnowledge').innerHTML=`<div class="card"><b>${escapeHtml(d.knowledge.status)}</b><small>${d.knowledge.indexChunks} chunks · ${d.knowledge.mapFiles} mapped files</small></div>${(d.knowledge.issues||[]).map(x=>`<div class="card"><small>${escapeHtml(x)}</small></div>`).join('')}`;
    $('cmdGraph').innerHTML=`<div class="card"><b>${d.missionGraph.summary.missions} missions</b><small>${d.missionGraph.summary.steps} steps · ${d.missionGraph.summary.dependencies} dependencies</small></div>`;
