function show(view){document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===view));const el=$(view);if(el)el.classList.add('active');if(view==='home')loadHome();if(view==='constellation')loadConstellation();if(view==='architect')loadArchitect();if(view==='commanddeck')loadCommandDeck();if(view==='nexus')loadNexus();if(view==='forge')loadForge();if(view==='portfolioos')loadPortfolioOS();if(view==='engineeringlab')loadEngineeringLab();if(view==='workstation')loadWorkstation();if(view==='learning')loadLearning();if(view==='chief')loadChief();if(view==='cognitive')loadCognitive();if(view==='command')loadCommandIntelligence();if(view==='executive')loadExecutive();if(view==='mission')loadMission();if(view==='memory')loadMemory();if(view==='files')loadFiles();if(view==='history')loadHistory();if(view==='knowledge')loadKnowledge();if(view==='autopilot')loadAutopilot();if(view==='focus')loadFocus();if(view==='project')loadProject();if(view==='governance')loadGovernance();if(view==='studio')loadStudio();if(view==='operations')loadOperations();if(view==='tasks'){loadTasks();loadApprovals();loadCheckpoints();}if(view==='diagnostics')refreshStatus();if(view==='enterprise500000')refreshV500000();if(view==='operating250000')refreshV250000();if(view==='continuous100000')refreshV100000()}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>show(b.dataset.view));

async function loadHome(){
 try{
  const h=await api('/api/home');
  $('homeReadiness').textContent=`${h.readiness?.score??0}/100`;$('homeReadinessDetail').textContent=`Grade ${h.readiness?.grade||'—'} · ${h.readiness?.checks?.filter(x=>x.ok).length||0}/${h.readiness?.checks?.length||0} checks healthy`;
  $('homeProject').textContent=h.activeProject?.name||'Workspace';$('homeProjectDetail').textContent=h.activeProject?`${h.activeProject.files||0} files${h.activeProject.frameworks?.length?' · '+h.activeProject.frameworks.join(', '):''}`:'Import or create a project in Workspace';
  $('homeMissions').textContent=String(h.activeMissions?.length||0);const lm=h.models?.loaded?.[0]?.name||h.models?.strong||'Auto';$('homeModel').textContent=lm;$('homeModelDetail').textContent=`fast ${h.models?.fast||'auto'} · code ${h.models?.code||'auto'}`;
  $('homeGoals').innerHTML=(h.goals||[]).length?h.goals.map(g=>`<div class="card"><div class="taskTop"><div><b>${escapeHtml(g.title)}</b><small>${escapeHtml(g.priority)} · ${g.progress||0}%</small></div><button onclick="completeGoal('${g.id}')">Done</button></div>${g.description?`<p>${escapeHtml(g.description)}</p>`:''}</div>`).join(''):'<div class="card emptyState">No active goals yet. Add one to give TravAI durable direction.</div>';
  $('homeMissionList').innerHTML=(h.recentMissions||[]).length?h.recentMissions.map(t=>`<div class="card"><b>${escapeHtml(t.title||'Mission')}</b><small>${escapeHtml(t.status||'')} · ${t.progress||0}%${t.qualityGate?.score!=null?' · quality '+t.qualityGate.score:'/100'}</small></div>`).join(''):'<div class="card emptyState">No missions yet.</div>';
  $('homeTeams').innerHTML=(h.teams||[]).map(t=>`<div class="teamRow"><div><b>${escapeHtml(t.name)}</b><small>${escapeHtml(t.purpose||'')}</small></div><span>${(t.agents||[]).length} agents</span></div>`).join('');
  const attention=[];(h.pendingApprovals||[]).forEach(a=>attention.push(`<div class="card attention"><b>Approval required</b><small>${escapeHtml(a.capability||a.reason||'Mission permission')}</small></div>`));(h.recoveryIssues||[]).slice(0,4).forEach(r=>attention.push(`<div class="card attention"><b>${escapeHtml(r.type||'Recovery')}</b><small>${escapeHtml(r.title||r.suggested||'Review recovery issue')}</small></div>`));$('homeAttention').innerHTML=attention.join('')||'<div class="card readiness ok"><b>Clear</b><small>No pending approvals or recovery issues.</small></div>';
 }catch(e){$('homeReadinessDetail').textContent=e.message}
}
window.completeGoal=async id=>{await api('/api/goals/update',{method:'POST',body:JSON.stringify({id,patch:{status:'done',progress:100}})});await loadHome()};

