  $('execCapability').textContent=`${c.score??0}/100`;$('execCapabilityGrade').textContent=c.grade||'—';$('execQueue').textContent=String(q.counts?.total||0);$('execQueueDetail').textContent=`${q.counts?.approvals||0} approvals · ${q.counts?.recovery||0} recovery · ${q.counts?.missions||0} missions`;$('execProjects').textContent=String((p.projects||[]).length);const active=(p.projects||[]).find(x=>x.id===p.activeProjectId)||(p.projects||[])[0];$('execProjectsDetail').textContent=active?`${active.name} · ${active.missions?.active||0} active · quality ${active.quality??'—'}`:'No project detected';$('execCalls').textContent=String(t.calls||0);$('execCallsDetail').textContent=`${t.localCalls||0} local · ${t.cloudCalls||0} cloud · ${t.errors||0} errors`;
