  $('execWorkQueue').innerHTML=(q.items||[]).slice(0,16).map(x=>`<div class="card"><div class="taskTop"><div><b>${escapeHtml(x.title)}</b><small>${escapeHtml(x.kind)} · priority ${x.priority}</small></div><span>${escapeHtml(x.detail||'')}</span></div></div>`).join('')||'<div class="card emptyState">Work queue is clear.</div>';
  $('execPortfolio').innerHTML=(p.projects||[]).map(x=>`<div class="card"><b>${escapeHtml(x.name)}</b><small>${x.missions?.active||0} active · ${x.missions?.done||0} completed · ${x.goals||0} goals${x.quality!=null?' · quality '+x.quality+'/100':''}</small><p>${escapeHtml((x.frameworks||[]).join(', ')||'Project')}</p></div>`).join('')||'<div class="card emptyState">No projects detected.</div>';
  $('execCapabilityChecks').innerHTML=(c.checks||[]).map(x=>`<div class="card ${x.ok?'readiness ok':'attention'}"><b>${x.ok?'✓':'!'} ${escapeHtml(x.label)}</b><small>${escapeHtml(x.detail||'')}</small>${!x.ok&&x.recommendation?`<p>${escapeHtml(x.recommendation)}</p>`:''}</div>`).join('');
  const g=d.graph?.stats||{};$('execGraphStats').innerHTML=`<div class="card"><b>${g.projects||0} projects</b><small>${g.goals||0} goals · ${g.missions||0} missions · ${g.memories||0} memories/outcomes</small></div><div class="card"><b>${d.graph?.edges?.length||0} relationships</b><small>locally derived project intelligence</small></div>`;
  $('execBrief').innerHTML=(d.briefs||[]).length?`<div class="card"><b>Latest executive brief</b><small>${escapeHtml(d.briefs[0].createdAt||'')}</small><p class="briefText">${escapeHtml(d.briefs[0].text||'').replaceAll('\n','<br>')}</p></div>`:'<div class="card emptyState">Generate your first local executive brief.</div>';
