function addMsg(role,text,meta='',trace=[],perf={}){document.querySelector('.welcome')?.remove();const d=document.createElement('div');d.className='msg '+role;const tools=trace.map(t=>`<div class="tool">Tool: ${escapeHtml(t.name)}${t.output?.error?` · ${escapeHtml(t.output.error)}`:''}</div>`).join('');const perfText=perf?.tokensPerSecond?`<div class="perf">${escapeHtml(perf.tokensPerSecond)} tok/s${perf.outputTokens?` · ${escapeHtml(perf.outputTokens)} tokens`:''}${perf.totalMs?` · ${escapeHtml(perf.totalMs)} ms`:''}</div>`:'';d.innerHTML=`<div class="meta">${escapeHtml(meta||role)}</div><div class="body">${escapeHtml(text)}</div>${tools}${perfText}`;$('messages').appendChild(d);$('messages').scrollTop=$('messages').scrollHeight;return d}
function setWorking(on){$('send').disabled=on;$('send').textContent=on?'Working…':'Send';$('stop').hidden=!on;if(!on)abortController=null}
function parseSSEChunk(buffer,onEvent){let sep;while((sep=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,sep);buffer=buffer.slice(sep+2);let event='message',data='';for(const line of block.split('\n')){if(line.startsWith('event:'))event=line.slice(6).trim();if(line.startsWith('data:'))data+=line.slice(5).trim()}if(data){try{onEvent(event,JSON.parse(data))}catch{}}}return buffer}
async function saveConversation(){currentConversation.messages=history;currentConversation.updatedAt=new Date().toISOString();await api('/api/conversations',{method:'POST',body:JSON.stringify(currentConversation)})}
async function send(){const text=$('prompt').value.trim();if(!text)return;$('prompt').value='';addMsg('user',text,'You');history.push({role:'user',content:text});if(currentConversation.title==='New chat')currentConversation.title=text.slice(0,60);setWorking(true);$('liveStatus').textContent='Routing request…';let assistantEl=null,assistantText='',trace=[],route={};abortController=new AbortController();try{
  const r=await fetch('/api/chat/stream',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text,history:history.slice(0,-1),provider:$('provider').value}),signal:abortController.signal});if(!r.ok)throw new Error(`HTTP ${r.status}`);
  const reader=r.body.getReader(),decoder=new TextDecoder();let buf='';
  const onEvent=(event,data)=>{
    if(event==='route'){route=data;$('routeChip').textContent=`${data.intent} · ${data.model||data.provider}`;$('liveStatus').textContent=`${data.provider} → ${data.model}${data.tools?.length?` · ${data.tools.length} tools`:''}`}
    else if(event==='status'){$('liveStatus').textContent=data.message||''}
    else if(event==='tool'){trace.push(data);$('liveStatus').textContent=`Completed ${data.name}`}
    else if(event==='token'){if(!assistantEl)assistantEl=addMsg('assistant','',`${route.provider||'AI'} · ${route.model||''}`);assistantText+=data.text||'';assistantEl.querySelector('.body').textContent=assistantText;$('messages').scrollTop=$('messages').scrollHeight}
    else if(event==='done'){assistantText=data.message||assistantText;if(!assistantEl)assistantEl=addMsg('assistant',assistantText,`${data.provider} · ${data.model}`,data.trace||trace,data.performance||{});else{assistantEl.querySelector('.body').textContent=assistantText;(data.trace||trace).forEach(t=>{const el=document.createElement('div');el.className='tool';el.textContent=`Tool: ${t.name}${t.output?.error?` · ${t.output.error}`:''}`;assistantEl.appendChild(el)});if(data.performance?.tokensPerSecond){const p=document.createElement('div');p.className='perf';p.textContent=`${data.performance.tokensPerSecond} tok/s${data.performance.outputTokens?` · ${data.performance.outputTokens} tokens`:''}${data.performance.totalMs?` · ${data.performance.totalMs} ms`:''}`;assistantEl.appendChild(p)}}route=data;$('liveStatus').textContent='';}
    else if(event==='error')throw new Error(data.error||'Unknown agent error');
  };
  while(true){const {done,value}=await reader.read();if(done)break;buf+=decoder.decode(value,{stream:true});buf=parseSSEChunk(buf,onEvent)}
  if(!assistantText)assistantText='(No text response)';history.push({role:'assistant',content:assistantText});await saveConversation();
}catch(e){if(e.name==='AbortError'){addMsg('assistant','Stopped.','System');$('liveStatus').textContent=''}else{addMsg('assistant','Error: '+e.message,'System');$('liveStatus').textContent=''}}finally{setWorking(false)}}
