async function loadKnowledge(){
  try{
    const [idx,snaps,audit]=await Promise.all([api('/api/index/status'),api('/api/snapshots?limit=40'),api('/api/audit?limit=80')]);
    $('knowledgeFiles').textContent=idx.files??0;$('knowledgeChunks').textContent=idx.chunks??0;$('knowledgeEmbed').textContent=idx.embeddingModel||'Lexical';$('knowledgeBuilt').textContent=idx.builtAt?new Date(idx.builtAt).toLocaleString():'Never';
    $('snapshotList').innerHTML=snaps.length?snaps.map(x=>`<div class="card"><b>${escapeHtml(x.path)}</b><p>${escapeHtml(x.reason||'snapshot')}</p><small>${escapeHtml(x.createdAt||'')} · ${escapeHtml(x.bytes||0)} bytes</small><div class="cardActions"><button onclick="restoreSnapshot('${escapeHtml(x.id)}')">Restore</button></div></div>`).join(''):'<div class="card">No snapshots yet.</div>';
    $('auditLog').textContent=audit.length?audit.map(x=>`${x.ts||''}  ${x.event||''}  ${JSON.stringify(Object.fromEntries(Object.entries(x).filter(([k])=>!['ts','event'].includes(k))))}`).join('\n'):'No activity yet.';
  }catch(e){$('auditLog').textContent='Knowledge status error: '+e.message}
}
