async function loadFiles(){const f=await api('/api/files');$('fileList').innerHTML=f.filter(x=>x.type==='file').map(x=>`<div class="fileItem" data-path="${escapeHtml(x.path)}">📄 ${escapeHtml(x.path)}</div>`).join('')||'<div class="fileItem">Workspace is empty.</div>';document.querySelectorAll('.fileItem[data-path]').forEach(el=>el.onclick=async()=>{const p=el.dataset.path;const r=await api('/api/file?path='+encodeURIComponent(p));$('filePath').value=p;$('fileContent').value=r.content})}
