$('uploadFile').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>20*1024*1024)throw new Error('File exceeds 20 MB.');const buf=new Uint8Array(await f.arrayBuffer());let binary='';const chunk=0x8000;for(let i=0;i<buf.length;i+=chunk)binary+=String.fromCharCode(...buf.subarray(i,i+chunk));await api('/api/upload',{method:'POST',body:JSON.stringify({path:f.name,dataBase64:btoa(binary)})});await loadFiles();alert(`Uploaded ${f.name}`)}catch(err){alert('Upload failed: '+err.message)}finally{e.target.value=''}};
$('uploadFolder').onchange=async e=>{const files=[...(e.target.files||[])];if(!files.length)return;let ok=0,failed=[];try{for(const f of files){try{if(f.size>20*1024*1024)throw new Error('over 20 MB');const buf=new Uint8Array(await f.arrayBuffer());let binary='';const chunk=0x8000;for(let i=0;i<buf.length;i+=chunk)binary+=String.fromCharCode(...buf.subarray(i,i+chunk));const rel=f.webkitRelativePath||f.name;await api('/api/upload',{method:'POST',body:JSON.stringify({path:rel,dataBase64:btoa(binary)})});ok++}catch(err){failed.push(`${f.name}: ${err.message}`)}}await loadFiles();alert(`Imported ${ok} file(s)${failed.length?`\n${failed.length} failed:\n${failed.slice(0,8).join('\n')}`:''}`)}finally{e.target.value=''}};
