let taskPoll=null;
function taskButtons(x){
  const active=['planning','in_progress','reviewing','pausing','cancelling'].includes(x.status);
  const resumable=['paused','interrupted','failed','awaiting_approval'].includes(x.status);
  return `<div class="cardActions">${!active&&!resumable?`<button onclick="runTaskNow('${x.id}')">▶ Run</button>`:''}${resumable?`<button onclick="resumeTask('${x.id}')">↻ Resume</button>`:''}${active?`<button onclick="pauseTask('${x.id}')">Ⅱ Pause</button><button onclick="cancelTask('${x.id}')">■ Cancel</button>`:''}${['done','failed','needs_review','cancelled'].includes(x.status)?`<button onclick="replayMission('${x.id}')">Replay</button>`:''}<button onclick="removeTask('${x.id}')">Delete</button></div>`;
}
async function loadTasks(){try{const t=await api('/api/tasks');const active=t.some(x=>['planning','in_progress','reviewing','pausing','cancelling'].includes(x.status));$('taskList').innerHTML=t.length?t.map(x=>`<div class="card taskCard"><div class="taskTop"><b>${escapeHtml(x.title)}</b><span><span class="chip">${escapeHtml(x.mode||'balanced')}</span> <span class="chip">${escapeHtml(x.status)}</span></span></div><p>${escapeHtml(x.prompt||'')}</p>${x.risk?`<small><b>Risk:</b> ${escapeHtml(x.risk.level||'low')} · ${escapeHtml(String(x.risk.score??0))}/100${x.risk.flags?.length?` · ${x.risk.flags.map(escapeHtml).join(', ')}`:''}</small>`:''}${x.acceptance?.criteria?.length?`<details><summary>Acceptance criteria (${x.acceptance.criteria.length})</summary><ul>${x.acceptance.criteria.map(c=>`<li>${escapeHtml(c)}</li>`).join('')}</ul></details>`:''}${x.preflight?.length?`<small><b>Council:</b> ${x.preflight.map(p=>escapeHtml(p.role)).join(' · ')}</small>`:''}<div class="progress"><span style="width:${Number(x.progress||0)}%"></span></div><small>${escapeHtml(x.statusMessage||'')} ${x.currentStep?`· step ${x.currentStep}/${(x.steps||[]).length}`:''} · ${escapeHtml(x.updatedAt||x.createdAt||'')}</small>${Array.isArray(x.steps)&&x.steps.length?`<div class="taskSteps">${x.steps.map(s=>`<div><span>${s.status==='done'?'✓':s.status==='failed'?'!':s.status==='running'?'●':s.status==='verifying'?'◆':s.status==='repairing'?'↻':s.status==='blocked'?'⏸':'○'}</span> ${s.role?`<span class="chip">${escapeHtml(s.role)}</span> `:''}${escapeHtml(s.title)}${s.verification?`<small><b>Verification:</b> ${s.verification.ok?'PASS':'FAIL'} — ${escapeHtml(s.verification.summary||'')}</small>`:''}${s.result?`<small>${escapeHtml(s.result.slice(0,360))}</small>`:''}${s.error?`<small class="error">${escapeHtml(s.error)}</small>`:''}</div>`).join('')}</div>`:''}${x.review?`<p><b>Reviewer:</b> ${escapeHtml(x.review)}</p>`:''}${x.testResult?`<p><b>Project test:</b> ${escapeHtml(x.testResult.retest?.status||x.testResult.status||'unknown')} ${escapeHtml(x.testResult.script||x.testResult.reason||'')}</p>`:''}${x.startCheckpoint?`<small>Start checkpoint: ${escapeHtml(x.startCheckpoint.id)}</small>`:''}${x.endCheckpoint?`<small>Final checkpoint: ${escapeHtml(x.endCheckpoint.id)}</small>`:''}${x.changes?`<p><b>Workspace changes:</b> +${x.changes.added?.length||0} added · ~${x.changes.modified?.length||0} modified · -${x.changes.deleted?.length||0} deleted</p>`:''}${x.qualityGate?`<p><b>Final quality gate:</b> ${escapeHtml(String(x.qualityGate.score??0))}/100 · ${x.qualityGate.pass?'PASS':'NEEDS REVIEW'} — ${escapeHtml(x.qualityGate.summary||'')}</p>`:''}${x.result?`<p><b>Result:</b> ${escapeHtml(x.result)}</p>`:''}${x.error?`<p class="error">${escapeHtml(x.error)}</p>`:''}${taskButtons(x)}</div>`).join(''):'<div class="card">No agent tasks yet.</div>';if(active&&!taskPoll)taskPoll=setInterval(loadTasks,1500);if(!active&&taskPoll){clearInterval(taskPoll);taskPoll=null}}catch(e){$('taskList').innerHTML=`<div class="card">${escapeHtml(e.message)}</div>`}}
