    const b=(m.benchmark?.results||[]).filter(x=>x.ok);$('missionModels').innerHTML=`<div class="card"><b>Fast</b><p>${escapeHtml(m.settings?.fastModel||'Auto')}</p></div><div class="card"><b>Strong</b><p>${escapeHtml(m.settings?.strongModel||'Auto')}</p></div><div class="card"><b>Code</b><p>${escapeHtml(m.settings?.codeModel||'Auto')}</p></div>`+(b.length?b.map(x=>`<div class="card"><b>${escapeHtml(x.model)}</b><small>${escapeHtml(x.tokensPerSecond||'?')} tok/s</small></div>`).join(''):'');
