async function loadPortfolioOS(){
  try{
    const d=await api('/api/portfolio-os');
    $('portfolioScore').textContent=(d.score??0)+'/100';
    $('portfolioGrade').textContent=d.grade||'';
    $('portfolioProjects').textContent=d.graph?.counts?.projects??0;
    $('portfolioMissions').textContent=d.graph?.counts?.missions??0;
    $('portfolioReadiness').textContent=(d.ledger?.readiness??0)+'/100';
    const projects=(d.graph?.projects||[]).map(p=>'<div class="card"><div class="row"><b>'+escapeHtml(p.name)+'</b>'+(p.active?'<span class="chip">active</span>':'')+'</div><small>'+(p.missions||[]).length+' missions · '+(p.contracts||[]).length+' contract(s)</small></div>');
    projects.push('<div class="card"><b>Graph</b><small>'+(d.graph?.nodes?.length||0)+' nodes · '+(d.graph?.edges?.length||0)+' relationships</small></div>');
    $('portfolioGraph').innerHTML=projects.join('')||'<div class="empty">No projects detected.</div>';
    $('portfolioBlockers').innerHTML=(d.ledger?.blockers||[]).map(x=>'<div class="card"><div class="row"><b>'+escapeHtml(x.title)+'</b><span class="chip">'+escapeHtml(x.type)+'</span></div></div>').join('')||'<div class="card"><b>No high-priority autonomy blockers</b><small>The approval/recovery gate is clear.</small></div>';
    $('projectContracts').innerHTML=(d.contracts||[]).map(x=>'<div class="card"><div class="row"><b>'+escapeHtml(x.name)+'</b><span class="chip">Q'+x.qualityTarget+'</span></div><p>'+escapeHtml(x.mission||'')+'</p><small>'+(x.requiredTests||[]).length+' required tests · '+(x.forbiddenChanges||[]).length+' forbidden paths</small></div>').join('')||'<div class="empty">No project contracts yet.</div>';
    $('releaseTrains').innerHTML=(d.releaseTrains||[]).map(x=>'<div class="card"><div class="row"><b>'+escapeHtml(x.name)+'</b><span class="chip">'+escapeHtml(x.status||'planned')+'</span></div><p>'+escapeHtml(x.objective||'')+'</p><small>'+(x.projectIds||[]).length+' projects · '+(x.missionIds||[]).length+' missions · Q'+x.qualityTarget+'</small></div>').join('')||'<div class="empty">No release trains yet.</div>';
    $('evidenceBundles').innerHTML=(d.evidenceBundles||[]).map(x=>'<div class="card"><b>'+escapeHtml(x.mission?.title||x.taskId)+'</b><small>'+escapeHtml(x.createdAt||'')+' · '+(x.quality?.score??'—')+' quality · '+(x.evidence||[]).length+' evidence items</small></div>').join('')||'<div class="empty">Evidence bundles appear after governed missions are packaged.</div>';
  }catch(e){$('portfolioBlockers').innerHTML='<div class="card"><b>Portfolio OS error</b><small>'+escapeHtml(e.message)+'</small></div>'}
}
