window.v250000Release=async(id,action)=>{try{await v250000Api('/releases/action',{method:'POST',body:JSON.stringify({id,action})});await refreshV250000()}catch(e){alert(e.message)}};
async function runV250000(){try{const mission=document.getElementById('v250000Mission')?.value.trim()||'';await v250000Api('/run-loop',{method:'POST',body:JSON.stringify({mission})});await refreshV250000()}catch(e){alert(e.message)}}
document.getElementById('v250000Run')?.addEventListener('click',runV250000);document.getElementById('v250000Run2')?.addEventListener('click',runV250000);document.getElementById('v250000Refresh')?.addEventListener('click',refreshV250000);
