document.getElementById('v250000SelfTest')?.addEventListener('click',async()=>{try{const r=await v250000Api('/self-test',{method:'POST',body:'{}'});alert(`v250000 self-test: ${r.ok?'PASS':'FAIL'}\n${r.checks.map(x=>`${x.ok?'✓':'✗'} ${x.name}`).join('\n')}`);await refreshV250000()}catch(e){alert(e.message)}});


// TravAI v500000 — Autonomous Enterprise OS control surface
async function v500000Api(path,options={}){const r=await fetch('/api/v500000'+path,{headers:{'Content-Type':'application/json'},...options});const j=await r.json();if(!r.ok)throw new Error(j.error||'v500000 request failed');return j}
function v500000Card(html){return `<div class="card">${html}</div>`}
async function refreshV500000(){try{const d=await v500000Api('/control');const g=id=>document.getElementById(id);if(g('v500000Score'))g('v500000Score').textContent=`${d.enterpriseScore?.score??0}/100`;if(g('v500000Risks'))g('v500000Risks').textContent=(d.riskRegister||[]).filter(r=>r.status==='open'||r.status==='mitigating').length;if(g('v500000Programs'))g('v500000Programs').textContent=(d.programs||[]).filter(p=>!['completed','cancelled'].includes(p.status)).length;if(g('v500000Releases'))g('v500000Releases').textContent=(d.releaseTrains||[]).filter(r=>['planned','approved'].includes(r.status)).length;if(g('v500000Mission')&&!g('v500000Mission').value)g('v500000Mission').value=d.enterpriseMission||'';
 if(g('v500000Roles'))g('v500000Roles').innerHTML=(d.roles||[]).map(r=>v500000Card(`<b>${r.name}</b><small>${r.status}</small><p>${r.mission}</p>`)).join('');
 if(g('v500000Objectives'))g('v500000Objectives').innerHTML=(d.objectives||[]).map(o=>v500000Card(`<b>${o.title}</b><small>${o.status} · weight ${o.weight}%</small><p>${o.metric}: ${o.progress}% toward ${o.target}</p><button onclick="v500000Objective('${o.id}','approve')">Approve</button> <button onclick="v500000Objective('${o.id}','complete')">Complete</button>`)).join('')||v500000Card('<small>No objectives.</small>');
 if(g('v500000Budgets'))g('v500000Budgets').innerHTML=(d.budgets||[]).map(b=>v500000Card(`<b>${b.name}</b><small>${b.capacity}% capacity</small><p>${b.reason}</p>`)).join('')||v500000Card('<small>Run the enterprise loop to allocate capacity.</small>');
 if(g('v500000RiskList'))g('v500000RiskList').innerHTML=(d.riskRegister||[]).slice(0,30).map(r=>v500000Card(`<b>${r.title}</b><small>${r.severity} · score ${r.score} · ${r.status}</small><p>${r.signal}</p><button onclick="v500000Risk('${r.id}','approve-response')">Approve response</button> <button onclick="v500000Risk('${r.id}','close')">Close</button>`)).join('')||v500000Card('<small>No enterprise risks detected.</small>');
 if(g('v500000ProgramList'))g('v500000ProgramList').innerHTML=(d.programs||[]).slice(0,30).map(p=>v500000Card(`<b>${p.name}</b><small>${p.type} · ${p.status}</small><p>${p.reason}</p><p>Value ${p.value} · risk ${p.risk} · effort ${p.effort}</p><button onclick="v500000Program('${p.id}','approve')">Approve</button> <button onclick="v500000Program('${p.id}','start')">Start</button> <button onclick="v500000Program('${p.id}','complete')">Complete</button>`)).join('')||v500000Card('<small>No programs staged.</small>');
 if(g('v500000CapitalList'))g('v500000CapitalList').innerHTML=(d.capitalRequests||[]).slice(0,30).map(c=>v500000Card(`<b>${c.programName}</b><small>${c.status} · ${c.amount} budget units</small><p>${c.reason}</p><button onclick="v500000Capital('${c.id}','approve')">Approve</button> <button onclick="v500000Capital('${c.id}','reject')">Reject</button>`)).join('')||v500000Card('<small>No capital requests.</small>');
 if(g('v500000ReleaseList'))g('v500000ReleaseList').innerHTML=(d.releaseTrains||[]).slice(0,30).map(r=>v500000Card(`<b>${r.productName} ${r.release}</b><small>${r.status} · confidence ${r.confidence}% · ${new Date(r.plannedFor).toLocaleDateString()}</small><p>Q${r.gates.quality} · S${r.gates.security} · R${r.gates.reliability}</p><button onclick="v500000Release('${r.id}','approve')">Approve</button> <button onclick="v500000Release('${r.id}','promote')">Promote</button>`)).join('')||v500000Card('<small>No release trains.</small>');
 if(g('v500000ForecastList'))g('v500000ForecastList').innerHTML=(d.forecasts||[]).slice(0,12).map(f=>v500000Card(`<b>${f.scenario}</b><small>${f.iterations} simulations · spend ${f.outcomes.expectedSpend}</small><p>Value ${f.outcomes.portfolioValue} · risk ${f.outcomes.risk} · reliability ${f.outcomes.reliability} · delivery ${f.outcomes.deliveryConfidence}</p><p>${f.recommendation}</p>`)).join('')||v500000Card('<small>No forecasts yet.</small>');
 if(g('v500000Cycles'))g('v500000Cycles').innerHTML=(d.enterpriseCycles||[]).slice(0,8).map(c=>v500000Card(`<b>Cycle ${c.id.slice(0,8)}</b><small>${c.status} · ${c.completedAt?new Date(c.completedAt).toLocaleString():''}</small><p>${c.mission}</p><p>${c.summary?`Score ${c.summary.enterpriseScore?.score} · risks ${c.summary.activeRisks} · programs ${c.summary.programs} · forecast risk ${c.summary.forecast?.risk}`:''}</p>`)).join('')||v500000Card('<small>No enterprise cycles yet.</small>');
}catch(e){console.error(e)}}
window.v500000Objective=async(id,action)=>{try{await v500000Api('/objectives',{method:'POST',body:JSON.stringify({id,action})});await refreshV500000()}catch(e){alert(e.message)}};
window.v500000Risk=async(id,action)=>{try{await v500000Api('/risks/action',{method:'POST',body:JSON.stringify({id,action})});await refreshV500000()}catch(e){alert(e.message)}};
window.v500000Program=async(id,action)=>{try{await v500000Api('/programs/action',{method:'POST',body:JSON.stringify({id,action})});await refreshV500000()}catch(e){alert(e.message)}};
window.v500000Capital=async(id,action)=>{try{await v500000Api('/capital/action',{method:'POST',body:JSON.stringify({id,action})});await refreshV500000()}catch(e){alert(e.message)}};
window.v500000Release=async(id,action)=>{try{await v500000Api('/releases/action',{method:'POST',body:JSON.stringify({id,action})});await refreshV500000()}catch(e){alert(e.message)}};
async function runV500000(){try{const mission=document.getElementById('v500000Mission')?.value.trim()||'';await v500000Api('/run-loop',{method:'POST',body:JSON.stringify({mission})});await refreshV500000()}catch(e){alert(e.message)}}
document.getElementById('v500000Run')?.addEventListener('click',runV500000);document.getElementById('v500000Run2')?.addEventListener('click',runV500000);document.getElementById('v500000Refresh')?.addEventListener('click',refreshV500000);
document.getElementById('v500000Forecast')?.addEventListener('click',async()=>{try{await v500000Api('/forecast',{method:'POST',body:JSON.stringify({scenario:'Executive operator forecast'})});await refreshV500000()}catch(e){alert(e.message)}});
document.getElementById('v500000SelfTest')?.addEventListener('click',async()=>{try{const r=await v500000Api('/self-test',{method:'POST',body:'{}'});alert(`v500000 self-test: ${r.ok?'PASS':'FAIL'}\n${r.checks.map(x=>`${x.ok?'✓':'✗'} ${x.name}`).join('\n')}`);await refreshV500000()}catch(e){alert(e.message)}});

// v1000000 Sovereign Enterprise Intelligence
async function v1000000Api(path, opts={}){const r=await fetch('/api/v1000000'+path,{headers:{'content-type':'application/json'},...opts});const j=await r.json();if(!r.ok)throw new Error(j.error||'v1000000 request failed');return j}
function v1mCard(title,body,actions=''){return `<div class="card"><b>${esc(title)}</b><small>${esc(body||'')}</small>${actions}</div>`}
async function renderV1000000(){if(!document.getElementById('v1000000Score'))return;try{const c=await v1000000Api('/control');document.getElementById('v1000000Score').textContent=c.executiveScore;document.getElementById('v1000000Scenarios').textContent=c.stats.scenarios;document.getElementById('v1000000Incidents').textContent=c.incidentCommands.filter(x=>x.status!=='closed'&&x.status!=='cancelled').length;document.getElementById('v1000000Architecture').textContent=c.architectureInvestments.filter(x=>!['completed','cancelled'].includes(x.status)).length;document.getElementById('v1000000Roles').innerHTML=c.roles.map(x=>v1mCard(x.name,x.mission)).join('');document.getElementById('v1000000Cycles').innerHTML=c.executiveCycles.map(x=>v1mCard(`Cycle ${x.id.slice(0,8)}`,`${x.status} · executive score ${x.executiveScore}`)).join('')||'<small>No cycles yet.</small>';document.getElementById('v1000000ScenarioList').innerHTML=c.scenarioRuns.map(r=>v1mCard(r.mission||'Portfolio scenario',r.options.map(o=>`${o.name}: value ${o.value}, risk ${o.risk}, confidence ${o.confidence}`).join(' | '))).join('')||'<small>No scenarios yet.</small>';document.getElementById('v1000000Resources').innerHTML=c.resourcePlans.map(r=>v1mCard(`Resource plan ${r.id.slice(0,8)}`,r.allocations.map(a=>`${a.name} ${a.units}`).join(' · '),r.status==='proposed'?`<button onclick="v1mAction('resource/action','${r.id}','approve')">Approve</button>`:'')).join('')||'<small>No plans yet.</small>';document.getElementById('v1000000IncidentList').innerHTML=c.incidentCommands.map(x=>v1mCard(x.title,`${x.severity} · ${x.status}`,x.status==='proposed'?`<button onclick="v1mAction('incident/action','${x.id}','approve')">Approve command</button>`:'')).join('')||'<small>No incident commands.</small>';document.getElementById('v1000000ArchitectureList').innerHTML=c.architectureInvestments.map(x=>v1mCard(x.title,`${x.type} · leverage ${x.estimatedLeverage} · ${x.status}`,x.status==='proposed'?`<button onclick="v1mAction('architecture/action','${x.id}','approve')">Approve</button>`:'')).join('')||'<small>No architecture investments.</small>';document.getElementById('v1000000Learning').innerHTML=c.learningFabric.map(x=>v1mCard(x.hypothesis,`${x.status} · confidence ${x.confidence}`)).join('')||'<small>No learning links yet.</small>';}catch(e){toast(e.message,'error')}}
window.v1mAction=async(path,id,action)=>{try{await v1000000Api('/'+path,{method:'POST',body:JSON.stringify({id,action})});await renderV1000000();toast('Updated')}catch(e){toast(e.message,'error')}};
async function runV1mCycle(){try{await v1000000Api('/cycle',{method:'POST',body:JSON.stringify({mission:document.getElementById('v1000000Mission')?.value||''})});await renderV1000000();toast('Executive cycle planned')}catch(e){toast(e.message,'error')}}
async function runV1mScenario(){try{await v1000000Api('/scenario',{method:'POST',body:JSON.stringify({mission:document.getElementById('v1000000Mission')?.value||''})});await renderV1000000();toast('Scenario simulation complete')}catch(e){toast(e.message,'error')}}
document.getElementById('v1000000Run')?.addEventListener('click',runV1mCycle);document.getElementById('v1000000Run2')?.addEventListener('click',runV1mCycle);document.getElementById('v1000000Scenario')?.addEventListener('click',runV1mScenario);document.getElementById('v1000000Refresh')?.addEventListener('click',renderV1000000);document.getElementById('v1000000SelfTest')?.addEventListener('click',async()=>{try{const x=await v1000000Api('/self-test',{method:'POST',body:'{}'});toast(`v1000000 self-test ${x.passed}/${x.total}`);await renderV1000000()}catch(e){toast(e.message,'error')}});setTimeout(renderV1000000,700);


// v2000000 Sovereign Strategic Intelligence
async function v2mApi(path, opts={}){const r=await fetch('/api/v2000000'+path,{headers:{'content-type':'application/json'},...opts});const j=await r.json();if(!r.ok)throw new Error(j.error||'v2000000 request failed');return j}
function v2mCard(title,body,actions=''){return `<div class="card"><b>${esc(title)}</b><small>${esc(body)}</small>${actions?`<div class="row">${actions}</div>`:''}</div>`}
async function renderV2m(){if(!document.getElementById('v2mScore'))return;try{const c=await v2mApi('/control');document.getElementById('v2mScore').textContent=c.strategicScore;document.getElementById('v2mScenarios').textContent=c.stats.scenarios;document.getElementById('v2mInitiatives').textContent=c.stats.initiatives;document.getElementById('v2mRisks').textContent=c.stats.riskBooks;document.getElementById('v2mRoles').innerHTML=c.roles.map(x=>v2mCard(x.name,x.mission)).join('');document.getElementById('v2mCycles').innerHTML=c.strategicCycles.map(x=>v2mCard(`Cycle ${x.id.slice(0,8)}`,`${x.status} · strategic score ${x.strategicScore}`)).join('')||'<small>No strategic cycles yet.</small>';document.getElementById('v2mScenarioList').innerHTML=c.scenarioBooks.map(r=>v2mCard(r.mission||'Strategic scenario',r.options.map(o=>`${o.name}: value ${o.value}, resilience ${o.resilience}, risk ${o.risk}, confidence ${o.confidence}`).join(' | '))).join('')||'<small>No scenario books yet.</small>';document.getElementById('v2mInitiativeList').innerHTML=c.initiativePlans.map(x=>v2mCard(`Initiative plan ${x.id.slice(0,8)}`,x.initiatives.map(i=>`Q${i.quarter} ${i.title}`).join(' · '),x.status==='proposed'?`<button onclick="v2mAction('initiative/action','${x.id}','approve')">Approve plan</button>`:'')).join('')||'<small>No initiative plans.</small>';document.getElementById('v2mCapitalList').innerHTML=c.capitalPlans.map(x=>v2mCard(`Capital plan ${x.id.slice(0,8)}`,`${x.requests.reduce((a,r)=>a+r.requested,0)} / ${x.budget} units · ${x.status}`,x.status==='proposed'?`<button onclick="v2mAction('capital/action','${x.id}','approve')">Approve capital</button>`:'')).join('')||'<small>No capital plans.</small>';document.getElementById('v2mRiskList').innerHTML=c.riskBooks.map(x=>v2mCard(`Risk book ${x.id.slice(0,8)}`,x.items.map(i=>`${i.kind} ${i.score}`).join(' · '))).join('')||'<small>No risk books.</small>';document.getElementById('v2mRoadmapList').innerHTML=c.modernizationRoadmaps.map(x=>v2mCard(x.title,`leverage ${x.expectedLeverage} · ${x.status}`,x.status==='proposed'?`<button onclick="v2mAction('roadmap/action','${x.id}','approve')">Approve roadmap</button>`:'')).join('')||'<small>No roadmaps.</small>';document.getElementById('v2mLearning').innerHTML=c.learningLinks.map(x=>v2mCard(x.hypothesis,`${x.status} · confidence ${x.confidence}`)).join('')||'<small>No learning links yet.</small>';}catch(e){toast(e.message,'error')}}
window.v2mAction=async(path,id,action)=>{try{await v2mApi('/'+path,{method:'POST',body:JSON.stringify({id,action})});await renderV2m();toast('Updated')}catch(e){toast(e.message,'error')}};
async function runV2mCycle(){try{await v2mApi('/cycle',{method:'POST',body:JSON.stringify({mission:document.getElementById('v2mMission')?.value||''})});await renderV2m();toast('Strategic cycle planned')}catch(e){toast(e.message,'error')}}
document.getElementById('v2mRun')?.addEventListener('click',runV2mCycle);document.getElementById('v2mRun2')?.addEventListener('click',runV2mCycle);document.getElementById('v2mRefresh')?.addEventListener('click',renderV2m);document.getElementById('v2mSelfTest')?.addEventListener('click',async()=>{try{const x=await v2mApi('/self-test',{method:'POST',body:'{}'});toast(`v2000000 self-test ${x.passed}/${x.total}`);await renderV2m()}catch(e){toast(e.message,'error')}});setTimeout(renderV2m,650);
